import base64, hashlib, os, subprocess, sys, zlib
from pathlib import Path

for name, data in {'backend/app/logging_config.py': '', 'backend/app/triage_model/__init__.py': 'eJwDAAAAAAE=', 'backend/app/triage_model/dataset.py': '', 'backend/app/triage_model/model.py': '', 'backend/app/triage_model/infer.py': '', 'backend/app/triage_model/train_document.py': ''}.items():
    path = Path('/kaggle/working/edgelegal') / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(zlib.decompress(base64.b64decode(data)))

import torch
assert torch.cuda.is_available(), 'CUDA GPU required'
print(torch.cuda.get_device_name(), torch.cuda.get_device_properties(0).total_memory, flush=True)
subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', 'transformers==5.20.2', 'tokenizers==0.23.3', 'sentencepiece'], check=True)
data = next(p.parent for p in Path('/kaggle/input').rglob('best_model.pt')
            if (p.parent / 'train.json').is_file() and (p.parent / 'dev.json').is_file())
expected = {'best_model.pt':'7ea45d37671897f04267f5a9e187a28790631362c8231c99757db620da1cbc61',
             'train.json':'3bbd02df4cc256c2322e862039c52e35ddb776af4dc0e013c3c5f27da6458d2e',
             'dev.json':'ec35aa76c04debfba8e4bc813a3eacde1727a03871cff71c8f60b4dbb37cf15d'}
for name, digest in expected.items():
    with (data/name).open('rb') as stream:
        assert hashlib.file_digest(stream, 'sha256').hexdigest() == digest, name
os.chdir('/kaggle/working/edgelegal')
command = [sys.executable, '-u', '-m', 'backend.app.triage_model.train_document',
           '--data-dir', str(data), '--checkpoint', str(data/'best_model.pt'), '--window-batch', '2', '--evidence-weight', '0']
subprocess.run(command + ['--out', '/kaggle/working/document-nli'], check=True)


